package dev.studyforge.banking.adapter.inmemory; import dev.studyforge.banking.application.*; import dev.studyforge.banking.domain.*; import java.util.*; public final class InMemoryAccountRepository implements AccountRepository{private final Map<AccountId,Account> data=new HashMap<>(); public Optional<Account> findById(AccountId id){return Optional.ofNullable(data.get(id));} public void add(Account a){if(data.putIfAbsent(a.id(),a)!=null)throw new DuplicateAccountException(a.id());} public void save(Account a){data.put(a.id(),a);} Map<AccountId,Account> copy(){return new HashMap<>(data);} void replace(Map<AccountId,Account> m){data.clear();data.putAll(m);}}
